import 'dart:convert';import 'dart:io';import 'package:flutter_test/flutter_test.dart';import 'package:glucotrack/l10n/app_localizations.dart';import 'package:glucotrack/l10n/translation_loader.dart';void main(){TestWidgetsFlutterBinding.ensureInitialized();test('writes English source values for SOS fallback keys',() async{await loadCoreTranslations();final k=(jsonDecode(File('reports/sos-fallback-keys.json').readAsStringSync())as List).cast<String>();const e=AppLocalizations('en');File('reports/sos-fallback-source.json').writeAsStringSync(jsonEncode({for(final x in k)x:e.t(x)}));expect(k,isNotEmpty);});}
